#include <stdio.h>
#include <stdarg.h>

static int print_unsigned(unsigned long long v, unsigned base) {
    const char *digits = "0123456789abcdef";
    char buf[32];
    int len = 0;
    do {
        buf[len++] = digits[v % base];
        v /= base;
    } while (v > 0);
    for (int i = len - 1; i >= 0; i--) putchar(buf[i]);
    return len;
}

static int print_int(int n) {
    long long v = n;
    int printed = 0;
    if (v < 0) {
        putchar('-');
        printed++;
        v = -v;
    }
    return printed + print_unsigned((unsigned long long)v, 10);
}

static int print_string(const char *s) {
    int printed = 0;
    for (; *s != '\0'; s++) {
        putchar(*s);
        printed++;
    }
    return printed;
}

int mini_printf(const char *fmt, ...) {
    va_list args;
    va_start(args, fmt);
    int printed = 0;
    for (const char *p = fmt; *p != '\0'; p++) {
        if (*p != '%') {
            putchar(*p);
            printed++;
            continue;
        }
        p++;
        if (*p == 'd') printed += print_int(va_arg(args, int));
        else if (*p == 's') printed += print_string(va_arg(args, const char *));
        else if (*p == 'x') printed += print_unsigned(va_arg(args, unsigned int), 16);
        else if (*p == 'c') {
            putchar(va_arg(args, int));
            printed++;
        } else {
            putchar(*p);
            printed++;
        }
    }
    va_end(args);
    return printed;
}

int main(void) {
    int n;
    char w[32];
    scanf("%d %31s", &n, w);
    int a = mini_printf("n=%d w=%s\n", n, w);
    int b = mini_printf("hex %x, first %c, 100%%\n", n, w[0]);
    int c = mini_printf("[%s|%d]\n", w, n / 2);
    printf("%d %d %d\n", a, b, c);
    return 0;
}
